import random, time

def call_with_retry(fn, attempts=5, base=0.2, cap=5.0):
    for i in range(attempts):
        try:
            return fn()
        except TransientError:
            if i == attempts - 1:
                raise
            # full jitter
            time.sleep(random.uniform(0, min(cap, base * 2 ** i)))
